import { _decorator, Component, Graphics, Node, Color } from 'cc';
import { EntityView } from './Engine/ViewRegistry';
import type { Entity } from './Engine/Entity';

const { ccclass } = _decorator;

// 临时的 View，用 Graphics 画个方块
export class TestView extends Component implements EntityView {
    private _entity: Entity | null = null;
    private _graphics: Graphics = null!;

    onLoad() {
        this._graphics = this.node.addComponent(Graphics);
        // 画一个 40x40 的方块（红色）
        this._graphics.fillColor = new Color(255, 80, 80, 255);
        this._graphics.rect(-20, -20, 40, 40);
        this._graphics.fill();
    }

   

    bind(entity: Entity): void {
        this._entity = entity;
        this.sync(0);
    }

    sync(dt: number): void {
        if (!this._entity) return;
        this.node.setPosition(this._entity.x, this._entity.y);
    }

    unbind(): void {
        this._entity = null;
    }
}